PRAGMA foreign_keys = ON;
CREATE TABLE data_schema_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO data_schema_meta(key,value) VALUES ('schema_version','1');
CREATE TABLE data_users (id TEXT PRIMARY KEY,first_seen_at INTEGER NOT NULL,last_seen_at INTEGER NOT NULL);
CREATE TABLE data_applications (client_id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE data_application_scopes (client_id TEXT NOT NULL,scope TEXT NOT NULL CHECK(scope IN ('profile:read','profile:write','roster:read','roster:write','equipment:read','equipment:write','decks:read','decks:write')),created_at INTEGER NOT NULL,PRIMARY KEY(client_id,scope),FOREIGN KEY(client_id) REFERENCES data_applications(client_id) ON DELETE CASCADE);
CREATE TABLE game_accounts (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,nickname TEXT NOT NULL CHECK(length(trim(nickname))>0),server_code TEXT NOT NULL CHECK(length(trim(server_code))>0),is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(user_id) REFERENCES data_users(id) ON DELETE CASCADE);
CREATE INDEX idx_game_accounts_user ON game_accounts(user_id); CREATE UNIQUE INDEX idx_game_accounts_one_primary ON game_accounts(user_id) WHERE is_primary=1;
CREATE TABLE game_tactics (id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT,rarity TEXT,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE game_generals (id TEXT PRIMARY KEY,name TEXT NOT NULL,unique_tactic_id TEXT,rarity TEXT,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}',FOREIGN KEY(unique_tactic_id) REFERENCES game_tactics(id) ON DELETE SET NULL);
CREATE TABLE game_equipment_templates (id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('weapon','mount')),name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE game_stat_types (id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE game_equipment_traits (id TEXT PRIMARY KEY,name TEXT NOT NULL,equipment_type TEXT CHECK(equipment_type IN ('weapon','mount','any')),description TEXT,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE game_promotion_items (id TEXT PRIMARY KEY,name TEXT NOT NULL,item_type TEXT,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE game_seasons (id TEXT PRIMARY KEY,name TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE user_generals (account_id TEXT NOT NULL,general_id TEXT NOT NULL,owned INTEGER NOT NULL DEFAULT 1 CHECK(owned IN (0,1)),breakthrough INTEGER NOT NULL DEFAULT 0 CHECK(breakthrough BETWEEN 0 AND 5),promotion INTEGER NOT NULL DEFAULT 0 CHECK(promotion>=0),favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)),note TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(account_id,general_id),FOREIGN KEY(account_id) REFERENCES game_accounts(id) ON DELETE CASCADE,FOREIGN KEY(general_id) REFERENCES game_generals(id) ON DELETE RESTRICT);
CREATE TABLE user_tactics (account_id TEXT NOT NULL,tactic_id TEXT NOT NULL,owned INTEGER NOT NULL DEFAULT 1 CHECK(owned IN (0,1)),breakthrough INTEGER NOT NULL DEFAULT 0 CHECK(breakthrough BETWEEN 0 AND 5),favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)),note TEXT,updated_at INTEGER NOT NULL,PRIMARY KEY(account_id,tactic_id),FOREIGN KEY(account_id) REFERENCES game_accounts(id) ON DELETE CASCADE,FOREIGN KEY(tactic_id) REFERENCES game_tactics(id) ON DELETE RESTRICT);
CREATE TABLE user_promotion_items (account_id TEXT NOT NULL,promotion_item_id TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),updated_at INTEGER NOT NULL,PRIMARY KEY(account_id,promotion_item_id),FOREIGN KEY(account_id) REFERENCES game_accounts(id) ON DELETE CASCADE,FOREIGN KEY(promotion_item_id) REFERENCES game_promotion_items(id) ON DELETE RESTRICT);
CREATE TABLE user_equipment (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,template_id TEXT NOT NULL,nickname TEXT,locked INTEGER NOT NULL DEFAULT 0 CHECK(locked IN (0,1)),favorite INTEGER NOT NULL DEFAULT 0 CHECK(favorite IN (0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(account_id) REFERENCES game_accounts(id) ON DELETE CASCADE,FOREIGN KEY(template_id) REFERENCES game_equipment_templates(id) ON DELETE RESTRICT);
CREATE INDEX idx_user_equipment_account ON user_equipment(account_id);
CREATE TABLE user_equipment_stats (equipment_id TEXT NOT NULL,slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 2),stat_type_id TEXT NOT NULL,value REAL NOT NULL,PRIMARY KEY(equipment_id,slot),FOREIGN KEY(equipment_id) REFERENCES user_equipment(id) ON DELETE CASCADE,FOREIGN KEY(stat_type_id) REFERENCES game_stat_types(id) ON DELETE RESTRICT);
CREATE TABLE user_equipment_traits (equipment_id TEXT NOT NULL,slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 2),trait_id TEXT NOT NULL,PRIMARY KEY(equipment_id,slot),FOREIGN KEY(equipment_id) REFERENCES user_equipment(id) ON DELETE CASCADE,FOREIGN KEY(trait_id) REFERENCES game_equipment_traits(id) ON DELETE RESTRICT);
CREATE TABLE decks (id TEXT PRIMARY KEY,account_id TEXT NOT NULL,name TEXT NOT NULL CHECK(length(trim(name))>0),season_id TEXT,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','candidate','research','archived')),visibility TEXT NOT NULL DEFAULT 'private' CHECK(visibility IN ('private','alliance','public')),note TEXT,is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN (0,1)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,FOREIGN KEY(account_id) REFERENCES game_accounts(id) ON DELETE CASCADE,FOREIGN KEY(season_id) REFERENCES game_seasons(id) ON DELETE SET NULL);
CREATE INDEX idx_decks_account ON decks(account_id);
CREATE TABLE deck_general_slots (deck_id TEXT NOT NULL,position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 3),general_id TEXT NOT NULL,weapon_instance_id TEXT,mount_instance_id TEXT,PRIMARY KEY(deck_id,position),FOREIGN KEY(deck_id) REFERENCES decks(id) ON DELETE CASCADE,FOREIGN KEY(general_id) REFERENCES game_generals(id) ON DELETE RESTRICT,FOREIGN KEY(weapon_instance_id) REFERENCES user_equipment(id) ON DELETE SET NULL,FOREIGN KEY(mount_instance_id) REFERENCES user_equipment(id) ON DELETE SET NULL);
CREATE TABLE deck_tactic_slots (deck_id TEXT NOT NULL,general_position INTEGER NOT NULL CHECK(general_position BETWEEN 1 AND 3),slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 2),tactic_id TEXT NOT NULL,PRIMARY KEY(deck_id,general_position,slot),FOREIGN KEY(deck_id) REFERENCES decks(id) ON DELETE CASCADE,FOREIGN KEY(tactic_id) REFERENCES game_tactics(id) ON DELETE RESTRICT);
CREATE TABLE deck_settings (deck_id TEXT PRIMARY KEY,settings_json TEXT NOT NULL DEFAULT '{}',updated_at INTEGER NOT NULL,FOREIGN KEY(deck_id) REFERENCES decks(id) ON DELETE CASCADE);
CREATE TABLE deck_snapshots (id TEXT PRIMARY KEY,source_deck_id TEXT,owner_user_id TEXT NOT NULL,visibility TEXT NOT NULL DEFAULT 'alliance' CHECK(visibility IN ('alliance','public')),snapshot_json TEXT NOT NULL,created_at INTEGER NOT NULL,FOREIGN KEY(source_deck_id) REFERENCES decks(id) ON DELETE SET NULL,FOREIGN KEY(owner_user_id) REFERENCES data_users(id) ON DELETE CASCADE);
CREATE INDEX idx_deck_snapshots_owner ON deck_snapshots(owner_user_id);
